function coinChange(coins, amount) {
  const memo = new Map();                        // left -> fewest coins
  const fewest = (left) => {                     // fewest coins that make exactly left
    if (left === 0) return 0;
    if (memo.has(left)) return memo.get(left);
    let best = Infinity;
    for (const c of coins) {
      if (c <= left) best = Math.min(best, fewest(left - c) + 1);   // c is the last coin
    }
    memo.set(left, best);
    return best;
  };
  const answer = fewest(amount);
  return answer === Infinity ? -1 : answer;
}

