int fewest(int[] coins, int left) {              // fewest coins that make exactly left
    if (left == 0) return 0;
    if (memo[left] != 0) return memo[left];
    int best = Integer.MAX_VALUE;
    for (int c : coins) {
        if (c > left) continue;
        int rest = fewest(coins, left - c);
        if (rest != Integer.MAX_VALUE) best = Math.min(best, rest + 1);   // c is the last coin
    }
    memo[left] = best;
    return best;
}

vector<int> memo;                                // -2 = not solved yet, -1 = impossible

int fewest(vector<int>& coins, int left) {       // fewest coins that make exactly left
    if (left == 0) return 0;
    if (memo[left] != -2) return memo[left];
    int best = -1;
    for (int c : coins) {
        if (c > left) continue;
        int rest = fewest(coins, left - c);
        if (rest != -1 && (best == -1 || rest + 1 < best)) best = rest + 1;   // c is the last coin
    }
    return memo[left] = best;
}

int coinChange(vector<int>& coins, int amount) {
    memo.assign(amount + 1, -2);
    return fewest(coins, amount);
}

