function coinChange(coins, amount) {
  if (amount === 0) return 0;
  const seen = new Array(amount + 1).fill(false);
  let level = [0];                               // amounts made with used - 1 coins
  for (let used = 1; level.length; used++) {
    const next = [];
    for (const a of level) {
      for (const c of coins) {
        if (c > amount - a) continue;            // overshoots
        const b = a + c;
        if (b === amount) return used;           // the first time we reach it is the fewest
        if (!seen[b]) {
          seen[b] = true;
          next.push(b);
        }
      }
    }
    level = next;
  }
  return -1;
}

def coin_change(coins, amount):
    if amount == 0:
        return 0
    seen = [False] * (amount + 1)
    level = [0]                           # amounts made with used - 1 coins
    used = 1
    while level:
        nxt = []
        for a in level:
            for c in coins:
                b = a + c
                if b == amount:
                    return used           # the first time we reach it is the fewest
                if b < amount and not seen[b]:
                    seen[b] = True
                    nxt.append(b)
        level = nxt
        used += 1
    return -1

